-- Create "feeds" table
CREATE TABLE "feeds" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "label" character varying NOT NULL, "path" character varying NOT NULL, "format" character varying NOT NULL DEFAULT 'rss', "status" bigint NOT NULL DEFAULT 1, "content_types" character varying NOT NULL DEFAULT '', "term_ids" character varying NOT NULL DEFAULT '', "item_limit" bigint NOT NULL DEFAULT 50, "days" bigint NOT NULL DEFAULT 0, "title" character varying NOT NULL DEFAULT '', "description" character varying NOT NULL DEFAULT '', "language" character varying NOT NULL DEFAULT '', "image_style" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "feeds_path" to table: "feeds"
CREATE UNIQUE INDEX "feeds_path" ON "feeds" ("path");
-- Create "feed_field_maps" table
CREATE TABLE "feed_field_maps" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "feed_id" bigint NOT NULL, "content_type" character varying NOT NULL, "body_field" character varying NOT NULL DEFAULT '', "image_field" character varying NOT NULL DEFAULT '', "category_field" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "feed_field_maps_feed_type" to table: "feed_field_maps"
CREATE UNIQUE INDEX "feed_field_maps_feed_type" ON "feed_field_maps" ("feed_id", "content_type");
